SELECT tblCase.CaseID, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_") AS FileNumber, [Last_Name] & ", " & [First_Name] AS Name, tblCase.Orig_Atty, tblCase.HandlingAtty_Case, qryTakeOff_advanced_AR.SumOfCharge AS SumOfAdvancedAR, qryTakeOff_cost_hold.CostHold, qryTakeOff_uncleared_deposits.SumOfDebit AS SumOfUnclearedDeposits, qryTakeOff_trust_account.Balance, qryTakeOff_unchashed_checks.SumOfCredit AS SumOfUncashedChecks, [Balance]-Nz([SumOfUnclearedDeposits],0) AS AvailBalance, [Balance]+Nz([SumOfUncashedChecks],0)-Nz([SumOfUnclearedDeposits],0) AS BankBalance, qry_TimeKeeping_CaseID_totals.SumOfTotal, qry_TimeKeeping_CaseID_totals.IANumber, qry_TimeKeeping_CaseID_totals.Bill_ID
FROM (((((tblCase LEFT JOIN qryTakeOff_advanced_AR ON tblCase.CaseID = qryTakeOff_advanced_AR.CaseID) LEFT JOIN qryTakeOff_cost_hold ON tblCase.CaseID = qryTakeOff_cost_hold.CaseID) LEFT JOIN qryTakeOff_trust_account ON tblCase.CaseID = qryTakeOff_trust_account.CaseID) LEFT JOIN qryTakeOff_unchashed_checks ON tblCase.CaseID = qryTakeOff_unchashed_checks.CaseID) LEFT JOIN qryTakeOff_uncleared_deposits ON tblCase.CaseID = qryTakeOff_uncleared_deposits.CaseID) LEFT JOIN qry_TimeKeeping_CaseID_totals ON tblCase.CaseID = qry_TimeKeeping_CaseID_totals.CaseID
GROUP BY tblCase.CaseID, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_"), [Last_Name] & ", " & [First_Name], tblCase.Orig_Atty, tblCase.HandlingAtty_Case, qryTakeOff_advanced_AR.SumOfCharge, qryTakeOff_cost_hold.CostHold, qryTakeOff_uncleared_deposits.SumOfDebit, qryTakeOff_trust_account.Balance, qryTakeOff_unchashed_checks.SumOfCredit, qry_TimeKeeping_CaseID_totals.SumOfTotal, qry_TimeKeeping_CaseID_totals.IANumber, qry_TimeKeeping_CaseID_totals.Bill_ID
HAVING ((([Balance]-Nz([SumOfUnclearedDeposits],0))<>0)) OR ((([Balance]+Nz([SumOfUncashedChecks],0)-Nz([SumOfUnclearedDeposits],0))<>0)) OR (((qry_TimeKeeping_CaseID_totals.SumOfTotal)<>0)) OR (((qryTakeOff_unchashed_checks.SumOfCredit)<>0)) OR (((qryTakeOff_uncleared_deposits.SumOfDebit)<>0))
ORDER BY [Last_Name] & ", " & [First_Name];